all_trans = {
    "en": en_translations,
    "es": es_translations,
    "fr": fr_translations,
    "de": de_translations,
    "pt": pt_translations
}

for lang, data in all_trans.items():
    filepath = f"messages/{lang}.json"
    with open(filepath, "r", encoding="utf-8") as f:
        content = json.load(f)
    
    content.update(data)
    
    with open(filepath, "w", encoding="utf-8") as f:
        json.dump(content, f, indent=2, ensure_ascii=False)

